package com.bank.bignum;

import java.util.logging.*;

public class AdderDemo {
    private static final Logger log = Logger.getLogger(AdderDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Amount 465 stored reverse: 5 -> 6 -> 4
        DigitNode a = build(new int[]{5, 6, 4});
        // Amount 248 stored reverse: 8 -> 4 -> 2
        DigitNode b = build(new int[]{8, 4, 2});

        log.info("Adding two reverse-order digit streams (465 + 248)");
        BigNumberAdder adder = new BigNumberAdder();
        DigitNode sum = adder.add(a, b);

        StringBuilder reverseDigits = new StringBuilder();
        for (DigitNode n = sum; n != null; n = n.next) {
            reverseDigits.append(n.digit);
        }
        log.info("Result stream (reverse order) -> " + reverseDigits);
        log.info("Which reads as the amount -> " + reverseDigits.reverse());
    }

    private static DigitNode build(int[] digits) {
        DigitNode dummy = new DigitNode(0);
        DigitNode tail = dummy;
        for (int d : digits) {
            tail.next = new DigitNode(d);
            tail = tail.next;
        }
        return dummy.next;
    }
}

