class DigitNode {
    int digit;
    DigitNode next;

    DigitNode(int digit) {
        this.digit = digit;
    }
}

// ─── Would be in service/BigNumberAdder.java ───
class BigNumberAdder {
    // Column addition with carry. O(max(n,m)) time.
    DigitNode add(DigitNode a, DigitNode b) {
        DigitNode dummy = new DigitNode(0);
        DigitNode tail = dummy;
        int carry = 0;

        while (a != null || b != null || carry != 0) {
            int x = (a != null) ? a.digit : 0;   // missing digit = 0
            int y = (b != null) ? b.digit : 0;
            int sum = x + y + carry;

            tail.next = new DigitNode(sum % 10); // ones digit of this column
            tail = tail.next;
            carry = sum / 10;                    // carry to next column

            if (a != null) a = a.next;
            if (b != null) b = b.next;
        }
        return dummy.next;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
